arguments.command:
cd /workspace && python3 -c "
import os
total=0; entries=0
for base, dirs, files in os.walk('submission'):
    for name in dirs+files:
        p=os.path.join(base,name); entries+=1
        if os.path.isfile(p): total+=os.path.getsize(p)
print('entries:', entries, 'total bytes:', total)
for f in sorted(os.listdir('submission')):
    p='submission/'+f
    print('  %-22s %6d bytes  utf8=%s' % (f, os.path.getsize(p) if os.path.isfile(p) else -1,
        (open(p,'rb').read().decode('utf-8') is not None) if os.path.isfile(p) else True))
"
